repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('mia', 34), ('pia', 51), ('mia', 41), ('mia', 22), ('omar', 11), ('noor', 33)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.pool.py:
"""A pool of donations with a remembered total."""


class DonationPool:
    def __init__(self):
        self._donations = []
        self._total = None

    def add(self, donation):
        """Add one donation to the pool."""
        self._donations.append(donation)
        self._total = None

    def remove(self, donation):
        """Take one donation out of the pool."""
        self._donations.remove(donation)

    def total(self):
        """Return the total pounds of the donations in the pool."""
        if self._total is None:
            self._total = sum(x.pounds for x in self._donations)
        return self._total


def largest_pounds(donations):
    """Return the largest pounds, or None when there are no donations."""
    values = [x.pounds for x in donations]
    return max(values) if values else None


def describe_donation(donation):
    """Return a one-line description of a donation."""
    return "%s: %s" % (donation.donor, donation.pounds)
